def lu_decomposition(matrix: list[list[float]]) -> tuple[list[list[float]], list[list[float]]]:
    n = len(matrix)
    L = [[0.0] * n for _ in range(n)]
    U = [[0.0] * n for _ in range(n)]
    for i in range(n):
        L[i][i] = 1.0
        for j in range(i, n):
            s = sum(L[i][k] * U[k][j] for k in range(i))
            U[i][j] = matrix[i][j] - s
        for j in range(i + 1, n):
            s = sum(L[j][k] * U[k][i] for k in range(i))
            L[j][i] = (matrix[j][i] - s) / U[i][i]
    return L, U

import math

def cholesky_decomposition(matrix: list[list[float]]) -> list[list[float]]:
    n = len(matrix)
    L = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1):
            s = sum(L[i][k] * L[j][k] for k in range(j))
            if i == j:
                L[i][j] = math.sqrt(matrix[i][i] - s)
            else:
                L[i][j] = (1.0 / L[j][j] * (matrix[i][j] - s))
    return L

