import numpy as np

def classify_critical_points() -> dict:
    # For f(x, y) = x^3 + y^3 - 3xy
    # grad f = [3x^2 - 3y, 3y^2 - 3x] = 0
    # Points: (0,0) and (1,1)
    # Hessian H = [[6x, -3], [-3, 6y]]
    results = {}
    points = [(0, 0), (1, 1)]
    for x, y in points:
        H = np.array([[6*x, -3], [-3, 6*y]])
        eigvals = np.linalg.eigvals(H)
        if all(eigvals > 0):
            res = 'local minimum'
        elif all(eigvals < 0):
            res = 'local maximum'
        elif any(eigvals > 0) and any(eigvals < 0):
            res = 'saddle point'
        else:
            res = 'undefined'
        results[(x, y)] = res
    return results

