import numpy as np

def sigmoid_derivative(x):
    s = 1 / (1 + np.exp(-x))
    return s * (1 - s)

def relu_derivative(x):
    return np.where(x > 0, 1.0, 0.0)

def tanh_derivative(x):
    return 1 - np.tanh(x)**2

def leaky_relu_derivative(x, alpha=0.01):
    return np.where(x > 0, 1.0, alpha)

def swish_derivative(x, beta=1.0):
    s = 1 / (1 + np.exp(-beta * x))
    return s + beta * x * s * (1 - s)

import math

def get_derivative(f, x0, n, h=1e-5):
    # Central finite difference for nth derivative
    if n == 0: return f(x0)
    return (get_derivative(f, x0 + h, n - 1, h) - get_derivative(f, x0 - h, n - 1, h)) / (2 * h)

def taylor_approx(f, x0, n, x):
    result = 0
    for i in range(n + 1):
        deriv = get_derivative(f, x0, i)
        term = (deriv * ((x - x0) ** i)) / math.factorial(i)
        result += term
    return result

