def linear_lr_decay(current_step: int, total_steps: int, initial_lr: float, end_lr: float) -> float:
    if current_step <= 0:
        return float(initial_lr)
    if current_step >= total_steps:
        return float(end_lr)

    decay_factor = current_step / total_steps
    return initial_lr - (initial_lr - end_lr) * decay_factor

