def birthday_probability(n: int) -> float:
    if n > 365:
        return 1.0
    if n < 2:
        return 0.0

    prob_unique = 1.0
    for i in range(n):
        prob_unique *= (365 - i) / 365

    return round(1 - prob_unique, 4)

