import math

def hypergeometric_pmf(N: int, K: int, n: int, k: int) -> float:
    if k < max(0, n - (N - K)) or k > min(n, K):
        return 0.0

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return math.comb(n, r)

    numerator = nCr(K, k) * nCr(N - K, n - k)
    denominator = nCr(N, n)
    return numerator / denominator

def update_beta_posterior(alpha: float, beta: float, successes: int, failures: int) -> dict:
    alpha_prime = alpha + successes
    beta_prime = beta + failures
    posterior_mean = alpha_prime / (alpha_prime + beta_prime)
    return {'alpha': float(alpha_prime), 'beta': float(beta_prime), 'mean': float(posterior_mean)}

