    if node.children is None:
        return node

    node.children = [prune_tree(child, alpha) for child in node.children]

    total_child_impurity = sum(c.impurity * c.n_samples for c in node.children) / node.n_samples
    num_leaves = sum(1 if c.children is None else 0 for c in node.children)

    # Calculate effective alpha: (R(node) - R(subtree)) / (|subtree| - 1)
    # Simplified for binary pruning
    if (node.impurity - total_child_impurity) <= alpha:
        node.children = None
    return node

