class Node:
    def __init__(self, value=None, feature=None, threshold=None, left=None, right=None):
        self.value = value
        self.feature = feature
        self.threshold = threshold
        self.left = left
        self.right = right

class DecisionTreeRegressor:
    def __init__(self, max_depth=5):
        self.max_depth = max_depth

    def fit(self, X, y):
        self.tree = self._build_tree(X, y, 0)

    def _build_tree(self, X, y, depth):
        if depth >= self.max_depth or len(np.unique(y)) == 1:
            return Node(value=np.mean(y))

        best_mse = float('inf')
        best_split = None

        for feature_idx in range(X.shape[1]):
            thresholds = np.unique(X[:, feature_idx])
            for threshold in thresholds:
                left_mask = X[:, feature_idx] <= threshold
                right_mask = ~left_mask
                if sum(left_mask) == 0 or sum(right_mask) == 0: continue

                mse = (np.var(y[left_mask]) * sum(left_mask) + np.var(y[right_mask]) * sum(right_mask)) / len(y)
                if mse < best_mse:
                    best_mse, best_split = mse, (feature_idx, threshold, left_mask, right_mask)

        if not best_split: return Node(value=np.mean(y))
        return Node(feature=best_split[0], threshold=best_split[1], 
                    left=self._build_tree(X[best_split[2]], y[best_split[2]], depth + 1),
                    right=self._build_tree(X[best_split[3]], y[best_split[3]], depth + 1))

    def predict(self, X):
        return np.array([self._traverse(x, self.tree) for x in X])

    def _traverse(self, x, node):
        if node.value is not None: return node.value
        return self._traverse(x, node.left) if x[node.feature] <= node.threshold else self._traverse(x, node.right)

