import numpy as np

class GaussianNB:
    def fit(self, X, y):
        self.classes = np.unique(y)
        self.means = {c: np.mean(X[y == c], axis=0) for c in self.classes}
        self.vars = {c: np.var(X[y == c], axis=0) + 1e-9 for c in self.classes}
        self.priors = {c: np.mean(y == c) for c in self.classes}

    def _pdf(self, class_idx, x):
        mean = self.means[class_idx]
        var = self.vars[class_idx]
        numerator = np.exp(-((x - mean) ** 2) / (2 * var))
        denominator = np.sqrt(2 * np.pi * var)
        return numerator / denominator

    def predict(self, X):
        posteriors = []
        for c in self.classes:
            prior = np.log(self.priors[c])
            posterior = np.sum(np.log(self._pdf(c, X)), axis=1) + prior
            posteriors.append(posterior)
        return self.classes[np.argmax(np.array(posteriors), axis=0)]

