from itertools import combinations
from collections import Counter

def apriori(transactions, min_support):
    item_counts = Counter()
    for t in transactions:
        for item in t:
            item_counts[(item,)] += 1

    frequent_itemsets = {itemset: count for itemset, count in item_counts.items() if count >= min_support}
    current_frequent = list(frequent_itemsets.keys())

    k = 2
    while current_frequent:
        candidates = set()
        for i in range(len(current_frequent)):
            for j in range(i + 1, len(current_frequent)):
                union = sorted(set(current_frequent[i]) | set(current_frequent[j]))
                if len(union) == k:
                    candidates.add(tuple(union))

        candidate_counts = Counter()
        for cand in candidates:
            for t in transactions:
                if set(cand).issubset(set(t)):
                    candidate_counts[cand] += 1

        new_frequent = {itemset: count for itemset, count in candidate_counts.items() if count >= min_support}
        frequent_itemsets.update(new_frequent)
        current_frequent = list(new_frequent.keys())
        k += 1

    return frequent_itemsets

