def calculate_auc(y_true: list, y_scores: list) -> float:
    data = sorted(zip(y_scores, y_true), key=lambda x: x[0], reverse=True)
    pos_count = sum(y_true)
    neg_count = len(y_true) - pos_count

    tpr, fpr = 0.0, 0.0
    prev_fpr, prev_tpr = 0.0, 0.0
    auc = 0.0

    for _, label in data:
        if label == 1:
            tpr += 1 / pos_count
        else:
            fpr += 1 / neg_count

        auc += (fpr - prev_fpr) * (tpr + prev_tpr) / 2
        prev_fpr, prev_tpr = fpr, tpr

    return round(auc, 4)

