def average_pooling_2d(matrix: list[list[float]], kernel_size: int, stride: int) -> list[list[float]]:
    input_dim = len(matrix)
    output_dim = (input_dim - kernel_size) // stride + 1
    output = [[0.0 for _ in range(output_dim)] for _ in range(output_dim)]

    for i in range(output_dim):
        for j in range(output_dim):
            row_start = i * stride
            col_start = j * stride
            window_sum = 0.0
            for r in range(row_start, row_start + kernel_size):
                for c in range(col_start, col_start + kernel_size):
                    window_sum += matrix[r][c]
            output[i][j] = window_sum / (kernel_size * kernel_size)
    return output

