import math

def sobel_edge_detection(image):
    rows = len(image)
    cols = len(image[0])
    Gx = [[-1, 0, 1], [-2, 0, 2], [-1, 0, 1]]
    Gy = [[-1, -2, -1], [0, 0, 0], [1, 2, 1]]
    output = [[0.0 for _ in range(cols)] for _ in range(rows)]
    padded = [[0 for _ in range(cols + 2)] for _ in range(rows + 2)]
    for r in range(rows):
        for c in range(cols):
            padded[r+1][c+1] = image[r][c]
    for r in range(rows):
        for c in range(cols):
            sum_x, sum_y = 0, 0
            for i in range(3):
                for j in range(3):
                    sum_x += padded[r+i][c+j] * Gx[i][j]
                    sum_y += padded[r+i][c+j] * Gy[i][j]
            output[r][c] = round(math.sqrt(sum_x**2 + sum_y**2), 2)
    return output

