def create_guidance_mask(chunk_size: int, num_chunks: int, guidance_indices: list) -> np.ndarray:
    T = chunk_size * num_chunks
    mask = np.zeros((T, T), dtype=int)

    for c in range(num_chunks):
        start, end = c * chunk_size, (c + 1) * chunk_size
        # Intra-chunk attention
        mask[start:end, start:end] = 1

    # Global guidance injection
    for i in range(T):
        for g_idx in guidance_indices:
            mask[i, g_idx] = 1

    return mask

