class CharTokenizer:
    def __init__(self, text: str):
        self.stoi = {'<BOS>': 0, '<EOS>': 1}
        self.itos = {0: '<BOS>', 1: '<EOS>'}
        chars = sorted(list(set(text)))
        for i, char in enumerate(chars):
            self.stoi[char] = i + 2
            self.itos[i + 2] = char

    def encode(self, text: str) -> list:
        return [self.stoi['<BOS>']] + [self.stoi[c] for c in text] + [self.stoi['<EOS>']]

    def decode(self, indices: list) -> str:
        return ''.join([self.itos[i] for i in indices if self.itos[i] not in ['<BOS>', '<EOS>']])

import math

def calculate_perplexity(log_probs: list) -> float:
    # N is the number of tokens
    n = len(log_probs)
    if n == 0:
        return 0.0
    # Cross-entropy is the negative average log-likelihood
    cross_entropy = -sum(log_probs) / n
    # Perplexity is the exponent of cross-entropy
    return math.exp(cross_entropy)

