def beam_search_decoder(model_predict, start_token, k, max_len, vocab_size):
    beams = [[ [start_token], 0.0 ]]
    for _ in range(max_len - 1):
        candidates = []
        for seq, score in beams:
            probs = model_predict(seq)
            for token in range(vocab_size):
                candidate = [seq + [token], score - np.log(probs[token] + 1e-9)]
