def get_ngrams(text, n=5):
    tokens = text.lower().split()
    return {' '.join(tokens[i:i+n]) for i in range(len(tokens)-n+1)}

def detect_contamination(train_docs, test_docs, threshold=0.3):
    train_ngrams = [get_ngrams(doc) for doc in train_docs]
    contaminated_indices = []
    for idx, test_doc in enumerate(test_docs):
        test_ngrams = get_ngrams(test_doc)
        if not test_ngrams: continue
        for train_set in train_ngrams:
            intersection = len(test_ngrams.intersection(train_set))
            union = len(test_ngrams.union(train_set))
            if union > 0 and (intersection / union) >= threshold:
                contaminated_indices.append(idx)
                break
    return sorted(list(set(contaminated_indices)))

