class KVCacheManager:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.current_usage = 0

    def access(self, request_id: str):
        if request_id in self.cache:
            self.cache.pop(request_id)
            self.cache[request_id] = True

    def allocate(self, request_id: str, blocks: int):
        while self.current_usage + blocks > self.capacity and self.cache:
            evicted_id = next(iter(self.cache))
            self.current_usage -= self.cache.pop(evicted_id)
        if blocks <= self.capacity:
            self.cache[request_id] = blocks
            self.current_usage += blocks
            return True
        return False

