from collections import OrderedDict

def simulate_offloading(access_pattern, gpu_capacity, cpu_capacity):
    gpu_cache = OrderedDict()
    cpu_cache = OrderedDict()

    for block in access_pattern:
        if block in gpu_cache:
            gpu_cache.move_to_end(block)
        elif block in cpu_cache:
            del cpu_cache[block]
            if len(gpu_cache) >= gpu_capacity:
                evicted_key, _ = gpu_cache.popitem(last=False)
                cpu_cache[evicted_key] = True
            gpu_cache[block] = True
        else:
            if len(gpu_cache) >= gpu_capacity:
                evicted_key, _ = gpu_cache.popitem(last=False)
                if len(cpu_cache) >= cpu_capacity:
                    cpu_cache.popitem(last=False)
                cpu_cache[evicted_key] = True
            gpu_cache[block] = True
    return list(gpu_cache.keys())

