class ContinuousBatchingSimulator:
    def __init__(self, batch_size: int):
        self.batch_size = batch_size

    def simulate(self, requests: list) -> int:
        active_batch = []
        queue = list(requests)
        time_steps = 0

        while queue or active_batch:
            # Fill batch
            while len(active_batch) < self.batch_size and queue:
                active_batch.append(queue.pop(0))

            # Process one step for all in batch
            time_steps += 1
            for i in range(len(active_batch) - 1, -1, -1):
                active_batch[i] -= 1
                if active_batch[i] == 0:
                    active_batch.pop(i)
        return time_steps

