def schedule_inference(requests: list, chunk_size: int) -> list:
    queue = [{'p': r[0], 'd': r[1]} for r in requests]
    log = []
    while queue:
        for req in queue:
            if req['p'] > 0:
                take = min(req['p'], chunk_size)
                req['p'] -= take
                log.append('Prefill')
            elif req['d'] > 0:
                req['d'] -= 1
                log.append('Decode')
        queue = [r for r in queue if r['p'] > 0 or r['d'] > 0]
    return log

