def block_wise_fp8_quantize(tensor: list, block_size: int) -> dict:
    import math
    quantized = []
    scales = []
    for i in range(0, len(tensor), block_size):
        block = tensor[i:i+block_size]
        max_val = max(abs(x) for x in block)
        scale = max_val / 448.0 if max_val > 0 else 1.0
        scales.append(scale)
        for val in block:
            q = round(val / scale)
            quantized.append(max(-448, min(448, q)))
    return {'quantized_data': quantized, 'scales': scales}

