def cliff_walking_solver(algorithm='sarsa', episodes=500, alpha=0.1, gamma=0.95, epsilon=0.1):
    q_table = np.zeros((4, 12, 4))
    for _ in range(episodes):
        state = (3, 0)
        while state != (3, 11):
            if np.random.rand() < epsilon:
                action = np.random.randint(4)
            else:
                action = np.argmax(q_table[state])

            # Simulate step
            r, next_state = -1, state
            if action == 0: next_state = (max(0, state[0]-1), state[1])
            elif action == 1: next_state = (state[0], min(11, state[1]+1))
            elif action == 2: next_state = (min(3, state[0]+1), state[1])
            elif action == 3: next_state = (state[0], max(0, state[1]-1))

            if next_state[0] == 3 and 1 <= next_state[1] <= 10:
                r, next_state = -100, (3, 0)

            if algorithm == 'sarsa':
                next_action = np.argmax(q_table[next_state])
                q_table[state][action] += alpha * (r + gamma * q_table[next_state][next_action] - q_table[state][action])
